			if (event.getAmount() <= 1.0F)
				if (EnigmaticItems.FORBIDDEN_FRUIT.haveConsumedFruit(player)) {
					event.setAmount(event.getAmount()*ForbiddenFruit.regenerationSubtraction.getValue().asModifierInverted());
